package com.bank.cover;

import java.util.logging.Logger;

// Counts connected coverage clusters (islands) via DFS flood fill.
public class CoverageClusterCounter {

    private static final Logger log = Logger.getLogger(CoverageClusterCounter.class.getName());

    public int countClusters(char[][] grid) {
        if (grid == null || grid.length == 0) return 0;
        int count = 0;
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[0].length; c++) {
                if (grid[r][c] == '1') {  // new unvisited land
                    count++;
                    flood(grid, r, c);    // mark whole cluster
                }
            }
        }
        log.info("Coverage clusters found: " + count);
        return count;
    }

    private void flood(char[][] grid, int r, int c) {
        if (r < 0 || c < 0 || r >= grid.length || c >= grid[0].length
                || grid[r][c] == '0') {
            return; // out of bounds or water
        }
        grid[r][c] = '0';          // mark visited
        flood(grid, r + 1, c);
        flood(grid, r - 1, c);
        flood(grid, r, c + 1);
        flood(grid, r, c - 1);
    }
}
